import test from 'node:test';
import assert from 'node:assert/strict';
import {insightScenario} from './insight-helpers.js';

async function queued(s) {
  await s.api('PATCH','/issues/'+s.issue.id,{title:'Delivery boundary'});
  const result=await s.member('POST','/digests',{orgId:s.org.id});
  assert.equal(result.status,201);
  assert(result.data.count>0);
  const outbox=(await s.member('GET','/me/outbox?kind=digest')).data.items;
  assert.equal(outbox.length,1);
  assert.equal(outbox[0].payload.count,result.data.count);
  assert(outbox[0].textBody.includes(s.issue.key));
  return outbox[0];
}

test('private outbox reconstructs digest body count and identifiers after project grant revocation',()=>insightScenario(async s=>{
  const before=await queued(s);
  await s.api('PATCH','/orgs/'+s.org.id+'/members/'+s.memberUser.id,{role:'guest'});
  await s.api('POST','/projects/'+s.project.id+'/guests',{userId:s.memberUser.id});
  assert.equal((await s.member('GET','/me/outbox?kind=digest')).data.items[0].payload.count,before.payload.count);
  await s.api('DELETE','/projects/'+s.project.id+'/guests/'+s.memberUser.id);
  const filtered=(await s.member('GET','/me/outbox?kind=digest')).data.items[0];
  assert.equal(filtered.payload.count,0);
  assert.deepEqual(filtered.payload.notificationIds,[]);
  assert.equal(filtered.textBody,'');
  assert.equal(filtered.subject,'Crew: 0 unread updates');
  const digest=(await s.member('GET','/digests?orgId='+s.org.id)).data.items[0];
  assert.equal(digest.count,0);assert.equal(digest.textBody,'');
  const stored=s.server.ctx.db.prepare('SELECT * FROM outbox WHERE id=?').get(before.id);
  assert.equal(JSON.parse(stored.payload_json).count,before.payload.count);
  assert(stored.text_body.includes(s.issue.key));
}));

test('private outbox omits removed organization digests before cursor pagination without deleting history',()=>insightScenario(async s=>{
  const before=await queued(s);
  await s.api('DELETE','/orgs/'+s.org.id+'/members/'+s.memberUser.id);
  const response=await s.member('GET','/me/outbox?kind=digest&limit=1');
  assert.equal(response.status,200);assert.deepEqual(response.data.items,[]);assert.equal(response.data.nextCursor,null);
  assert.equal((await s.member('GET','/digests?orgId='+s.org.id)).status,403);
  assert(s.server.ctx.db.prepare('SELECT 1 FROM outbox WHERE id=?').get(before.id));
}));

test('delivery visibility retains recipient invite reset links and denies even wildcard API tokens',()=>insightScenario(async s=>{
  const other=(await s.api('POST','/orgs',{name:'Invitation destination'})).data.organization;
  await s.api('POST','/orgs/'+other.id+'/invitations',{email:s.memberUser.email,role:'member'});
  await s.member('POST','/auth/password/reset/request',{email:s.memberUser.email});
  const rows=(await s.member('GET','/me/outbox')).data.items;
  for(const kind of ['invite','reset']) {
    const row=rows.find(item=>item.kind===kind);assert(row);assert.equal(row.toEmail,s.memberUser.email);assert.match(row.payload.link,/token=/);
  }
  const token=(await s.member('POST','/tokens',{name:'Private delivery denial',scopes:['*']})).data.token;
  assert.equal((await s.member('GET','/me/outbox',undefined,{Authorization:'Bearer '+token})).status,403);
  const digest=(await s.member('GET','/digests?orgId='+s.org.id)).data;
  assert(!JSON.stringify(digest).includes('token='));
}));
